    let d = s.chars().next().unwrap()  // the single repeated digit as char
                  .to_digit(10).unwrap() as i32;

    // For each digit d' < d, we have 4 boring numbers: lengths 1 to 4,
    // each requiring length button presses to type.
    // So total presses for digits less than d is:
    // sum_{i=1 to (d-1)} (1+2+3+4) = (d-1) * 10
    //
    // Then for digit d itself, we sum presses for lengths from 1 up to k:
    // 1 + 2 + ... + k = k*(k+1)/2

    let presses_for_smaller_digits = (d - 1) * 10;
